function maximumBeauty(flowers, newFlowers, target, full, partial) {
  const gardens = flowers.map(f => Math.min(f, target)).sort((a, b) => a - b);
  const n = gardens.length;
  const prefix = [0];
  for (const g of gardens) {
    prefix.push(prefix[prefix.length - 1] + g);
  }
  let incomplete = n;
  while (incomplete > 0 && gardens[incomplete - 1] === target) {
    incomplete--;
  }
  let budget = newFlowers;
  let best = 0;
  while (budget >= 0) {
    const complete = n - incomplete;
    if (incomplete === 0) {
      best = Math.max(best, complete * full);
      break;
    }
    let low = 1;
    let high = incomplete;
    while (low < high) {
      const mid = Math.ceil((low + high) / 2);
      if (gardens[mid - 1] * mid - prefix[mid] <= budget) {
        low = mid;
      } else {
        high = mid - 1;
      }
    }
    const level = Math.min(target - 1, Math.floor((prefix[low] + budget) / low));
    best = Math.max(best, complete * full + level * partial);
    incomplete--;
    budget -= target - gardens[incomplete];
  }
  return best;
}

