function maximumBeauty(flowers, newFlowers, target, full, partial) {
  const n = flowers.length;
  let best = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    let cost = 0;
    let ok = true;
    const rest = [];
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) cost += Math.max(0, target - flowers[i]);
      else if (flowers[i] >= target) ok = false;
      else rest.push(flowers[i]);
    }
    if (!ok || cost > newFlowers) continue;
    const spare = newFlowers - cost;
    let level = 0;
    if (rest.length) {
      let lo = Math.min(...rest), hi = target - 1;
      while (lo < hi) {
        const L = lo + Math.ceil((hi - lo) / 2);
        let need = 0;
        for (const f of rest) need += Math.max(0, L - f);
        if (need <= spare) lo = L; else hi = L - 1;
      }
      level = lo;
    }
    const count = n - rest.length;
    best = Math.max(best, count * full + level * partial);
  }
  return best;
}

