function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 6);
    const target = int(1, 10);
    const flowers = Array.from({ length: n }, () => int(1, 12));
    return [flowers, int(1, 30), target, int(1, 10), int(1, 10)];
  }
  const n = 2000;
  const target = rand() < 0.2 ? int(1, 1000) : int(50000, 100000);
  const flowers = Array.from({ length: n }, () => int(1, 100000));
  let deficit = 0;
  for (const f of flowers) deficit += Math.max(0, target - f);
  const pick = rand();
  const newFlowers = pick < 0.15 ? 10000000000 : Math.max(1, Math.floor(rand() * deficit * 1.1));
  return [flowers, newFlowers, target, int(1, 100000), int(1, 100000)];
}
